    CONSTRAINT ck_commission_records_manual_bonus_ratio CHECK (((manual_bonus_ratio IS NULL) OR ((manual_bonus_ratio >= (0)::numeric) AND (manual_bonus_ratio <= (1)::numeric)))),
    CONSTRAINT ck_commission_records_operator_bonus_ratio CHECK (((operator_bonus_ratio >= (0)::numeric) AND (operator_bonus_ratio <= (1)::numeric))),
    CONSTRAINT ck_commission_records_payment_status CHECK (((payment_status)::text = ANY (ARRAY[('paid'::character varying)::text, ('unpaid'::character varying)::text]))),
    CONSTRAINT ck_commission_records_report_month_format CHECK (((report_month)::text ~~ '____-__'::text))
);


